import type { DrawerProps } from "./drawer.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { keyframes } from "@emotion/react";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import * as RadixDialog from "@radix-ui/react-dialog";
import { useMemo } from "react";

const componentName = "Drawer";

export const DrawerClasses = {
  root: "exp-textura_drawer",
  body: "exp-textura_drawer_body",
  title: "exp-textura_drawer_title",
  overlay: "exp-textura_drawer_overlay",
  content: "exp-textura_drawer_content",
  footer: "exp-textura_drawer_footer",
  closeIconButton: "exp-textura_drawer_close_icon-button",
  start: "exp-textura_drawer_start",
  end: "exp-textura_drawer_end",
  top: "exp-textura_drawer_top",
  bottom: "exp-textura_drawer_bottom",
  padding: "exp-textura_drawer_padding",
  push: "exp-textura_drawer_push",
  pushContent: "exp-textura_drawer_push_content",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  "ai-chat": {
    body: {
      boxShadow: "none",
    },
    padding: {
      padding: 0,
    },
    start: {
      "--drawer-width": theme.toRem(400),
      borderInlineEnd: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
    end: {
      "--drawer-width": theme.toRem(400),
      borderInlineStart: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
    top: {
      "--drawer-width": theme.toRem(400),
      borderBottom: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
    bottom: {
      "--drawer-width": theme.toRem(400),
      borderTop: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
  },
  divider: {
    body: {
      boxShadow: "none",
    },
    start: {
      borderInlineEnd: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
    end: {
      borderInlineStart: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
    top: {
      borderBottom: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
    bottom: {
      borderTop: `${theme.toRem(theme.border.width.sm)} solid ${theme.divider.default.color.default}`,
    },
  },
});

const generateStyles = (props: Omit<DrawerProps, "children">): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<DrawerProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  const transformClosed = {
    start: "translateX(-100%)",
    end: "translateX(100%)",
    top: "translateY(-100%)",
    bottom: "translateY(100%)",
  };

  const transformOpened = {
    start: "translateX(0)",
    end: "translateX(0)",
    top: "translateY(0)",
    bottom: "translateY(0)",
  };

  const slideIn = {
    start: keyframes`from { transform: ${transformClosed.start}; } to { transform: ${transformOpened.start}; }`,
    end: keyframes`from { transform: ${transformClosed.end}; } to { transform: ${transformOpened.end}; }`,
    top: keyframes`from { transform: ${transformClosed.top}; } to { transform: ${transformOpened.top}; }`,
    bottom: keyframes`from { transform: ${transformClosed.bottom}; } to { transform: ${transformOpened.bottom}; }`,
  };
  const slideOut = {
    start: keyframes`from { transform: ${transformOpened.start}; } to { transform: ${transformClosed.start}; }`,
    end: keyframes`from { transform: ${transformOpened.end}; } to { transform: ${transformClosed.end}; }`,
    top: keyframes`from { transform: ${transformOpened.top}; } to { transform: ${transformClosed.top}; }`,
    bottom: keyframes`from { transform: ${transformOpened.bottom}; } to { transform: ${transformClosed.bottom}; }`,
  };

  const finalOpacity = styleSlots?.overlay?.opacity ?? 1;

  const fadeIn = keyframes`from { opacity: 0; } to { opacity: ${finalOpacity}; }`;
  const fadeOut = keyframes`from { opacity: ${finalOpacity}; } to { opacity: 0; }`;

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    [`&.${DrawerClasses.overlay}`]: {
      position: "fixed",
      inset: 0,
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      backgroundColor: theme.overlay.background,
      zIndex: theme.zIndex.dynamic,
      animationDuration: "0.3s",
      '&[data-state="open"]': {
        animationName: fadeIn,
        opacity: finalOpacity,
      },
      '&[data-state="closed"]': {
        animationName: fadeOut,
        opacity: 0,
      },
      '&[data-textura-scoped="true"]': {
        position: "absolute",
      },
      ...styleSlots?.overlay,
    },

    [`&.${DrawerClasses.body}`]: {
      display: "flex",
      flexDirection: "column",
      position: "fixed",
      overflow: "auto",
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      backgroundColor: theme.drawer.color.background,
      color: theme.color.content.default,
      boxShadow: theme.dropShadow.lg,
      zIndex: theme.zIndex.dynamic,
      animationDuration: "0.3s",
      ...theme.typography.body.md,

      [`.${DrawerClasses.pushContent}`]: {
        display: "flex",
        flexDirection: "column",
        height: "100%",
        width: "100%",
        transition: "opacity 0.3s ease",
        position: "relative",
        ...styleSlots?.pushContent,
      },

      // Apply padding when the padding class is present
      [`&.${DrawerClasses.padding}, > .${DrawerClasses.padding}`]: {
        padding: theme.toRem(theme.spacing[24]),
        ...styleSlots?.padding,
      },

      '&[data-textura-scoped="true"]': {
        position: "absolute",
      },

      [`&.${DrawerClasses.start}`]: {
        top: 0,
        bottom: 0,
        left: 0,
        "--drawer-width": theme.toRem(500),
        width: "var(--drawer-width)",
        transform: transformClosed.start,
        '&[data-state="open"]': {
          animationName: slideIn.start,
          transform: transformOpened.start,
        },
        [`&[data-state="closed"]`]: {
          animationName: slideOut.start,
        },
        ":dir(rtl)": {
          left: "unset",
          right: 0,
          transform: transformClosed.end,
          '&[data-state="open"]': {
            animationName: slideIn.end,
            transform: transformOpened.end,
          },
          [`&[data-state="closed"]`]: {
            animationName: slideOut.end,
          },
        },
        ...styleSlots?.start,
      },

      [`&.${DrawerClasses.end}`]: {
        top: 0,
        bottom: 0,
        right: 0,
        "--drawer-width": theme.toRem(500),
        width: "var(--drawer-width)",
        transform: transformClosed.end,
        '&[data-state="open"]': {
          animationName: slideIn.end,
          transform: transformOpened.end,
        },
        [`&[data-state="closed"]`]: {
          animationName: slideOut.end,
        },
        ":dir(rtl)": {
          right: "unset",
          left: 0,
          transform: transformClosed.start,
          '&[data-state="open"]': {
            animationName: slideIn.start,
            transform: transformOpened.start,
          },
          [`&[data-state="closed"]`]: {
            animationName: slideOut.start,
          },
        },
        ...styleSlots?.end,
      },

      [`&.${DrawerClasses.top}`]: {
        top: 0,
        left: 0,
        right: 0,
        "--drawer-height": theme.toRem(500),
        height: "var(--drawer-height)",
        transform: transformClosed.top,
        '&[data-state="open"]': {
          animationName: slideIn.top,
          transform: transformOpened.top,
        },
        [`&[data-state="closed"]`]: {
          animationName: slideOut.top,
        },
        ...styleSlots?.top,
      },

      [`&.${DrawerClasses.bottom}`]: {
        bottom: 0,
        left: 0,
        right: 0,
        transform: transformClosed.bottom,
        "--drawer-height": theme.toRem(500),
        height: "var(--drawer-height)",
        '&[data-state="open"]': {
          animationName: slideIn.bottom,
          transform: transformOpened.bottom,
        },
        [`&[data-state="closed"]`]: {
          animationName: slideOut.bottom,
        },
        ...styleSlots?.bottom,
      },

      // Push mode overrides - moved to end to override direction transforms
      [`&.${DrawerClasses.push}`]: {
        position: "relative",
        zIndex: 1,
        boxShadow: "none",
        flexShrink: 0,
        overflow: "hidden",
        // In push mode, we animate width/height instead of just transform
        transition: "width 0.3s ease, height 0.3s ease, transform 0.3s ease",

        '&[data-state="closed"]': {
          padding: 0,
          border: 0,
          [`.${DrawerClasses.pushContent}`]: {
            opacity: 0,
          },
        },

        // Horizontal: Collapse Width
        [`&.${DrawerClasses.start}[data-state="closed"], &.${DrawerClasses.end}[data-state="closed"]`]:
          {
            width: 0,
          },

        // Vertical: Collapse Height
        [`&.${DrawerClasses.top}[data-state="closed"], &.${DrawerClasses.bottom}[data-state="closed"]`]:
          {
            height: 0,
          },

        '&[data-state="open"]': {
          transform: "none !important",
          animationName: "none !important",
        },

        [`&.${DrawerClasses.start}`]: { order: -1 },
        [`&.${DrawerClasses.end}`]: { order: 9999 },
        [`&.${DrawerClasses.top}`]: { order: -1 },
        [`&.${DrawerClasses.bottom}`]: { order: 9999 },
        ...styleSlots?.push,
      },

      ...styleSlots?.body,
    },

    [`& .${DrawerClasses.title}`]: {
      margin: 0,
      paddingBottom: theme.toRem(theme.spacing[16]),
      color: theme.color.content.strong,
      ...theme.typography.heading.sm,
      ...styleSlots?.title,
    },

    [`& .${DrawerClasses.content}`]: {
      flex: "1 1 auto",
      overflowY: "auto",
      ...theme.typography.body.md,
      ...styleSlots?.content,
    },

    [`& .${DrawerClasses.footer}`]: {
      margin: `${theme.toRem(theme.spacing[16])} 0 0`,
      ...styleSlots?.footer,
    },

    [`& .${DrawerClasses.closeIconButton}`]: {
      position: "absolute",
      top: theme.toRem(theme.spacing[8]),
      right: theme.toRem(theme.spacing[8]),
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      cursor: "pointer",
      background: "transparent",
      ":dir(rtl)": {
        right: "unset",
        left: theme.toRem(theme.spacing[8]),
      },
      "&:focus-visible": {
        ...styleSlots?.closeIconButtonFocus,
      },
      ...styleSlots?.closeIconButton,
    },
    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledDrawer = styled(RadixDialog.Content, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<DrawerProps, "children">>((props) => generateStyles(props));

export const StyledDrawerBody = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<DrawerProps, "children">>((props) => generateStyles(props));

export const StyledDrawerOverlay = styled(RadixDialog.Overlay, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<DrawerProps, "children">>((props) => generateStyles(props));
